import { ref, Ref } from 'vue';
import { createNativeDraggable, createNativeAutoScroll, INativeDragEvent } from '@/core/helpers/native-interaction';
import { createCoreData, offsetXYFromParentOf } from '@/core/helpers/draggable-utils';
import { calcColWidth, calcGridItemWH, clamp } from '@/core/griditem/helpers/grid-item-calculate-helper';
import { EGridItemEvent } from '@/core/griditem/enums/EGridItemEvents';
import { ICalcXy, IGridItemPosition } from '@/core/griditem/interfaces/grid-item.interfaces';
import { IEventsData } from '@/core/common/interfaces/event-bus.interfaces';
import { IGridItemDragContext } from './grid-item-composable-context';

/**
 * Encapsulates GridItem's dragging behavior: the native pointer-driven
 * drag engine's wiring (see `@/core/helpers/native-interaction.ts`),
 * translating pixel deltas to grid units, and the drag lifecycle
 * (dragstart/dragmove/dragend) that emits `move`/`moved` and feeds the
 * shared eventBus's `dragEvent`.
 *
 * Extracted from GridItem.vue as part of the Phase 2 structural cleanup —
 * see docs/REFACTORING.md's "GridItem.vue is doing too much" section and
 * docs/ARCHITECTURE.md for how this fits alongside `useGridItemResize`.
 */
/** Return shape of {@link useGridItemDrag}. */
export interface IUseGridItemDragReturn {
  calcXY: (top: number, left: number) => ICalcXy;
  draggable: Ref<boolean | null>;
  dragging: Ref<IGridItemPosition | undefined>;
  isDragging: Ref<boolean>;
  teardownDraggable: () => void;
  tryMakeDraggable: () => void;
}

export function useGridItemDrag(ctx: IGridItemDragContext): IUseGridItemDragReturn {
  const {
    bounded,
    cols,
    containerWidth,
    editModeEnabled,
    emit,
    eventBus,
    gridItem,
    innerH,
    innerW,
    innerX,
    innerY,
    isResizing,
    margin,
    maxRows,
    props,
    renderRtl,
    rowHeight,
    transformScale,
  } = ctx;

  /** `null` until `GridItem`'s `onMounted` resolves it from the `isDraggable` prop or the parent layout's default. */
  const draggable = ref<boolean | null>(null);
  /** Whether a drag is currently in progress — drives the `vue-draggable-dragging`/`disable-userselect` classes. */
  const isDragging = ref(false);
  /** Current pixel position while dragging; `undefined` when not dragging. */
  const dragging = ref<IGridItemPosition | undefined>(undefined);
  /** Previous tick's pointer x position, `NaN` before the first `dragmove` (see `createCoreData`). */
  const lastX = ref(NaN);
  /** Previous tick's pointer y position, `NaN` before the first `dragmove`. */
  const lastY = ref(NaN);
  /** Grid-unit x position at drag-start, used to detect whether a drag actually moved the item (for the `MOVED` event). */
  const previousX = ref<number | undefined>(undefined);
  /** Grid-unit y position at drag-start. */
  const previousY = ref<number | undefined>(undefined);
  /** The native draggable engine's own cleanup handle, once created — `undefined` until `tryMakeDraggable` first runs against a real, mounted element. */
  let nativeDraggable: { destroy: () => void } | undefined;
  /** Backing the `autoScroll` prop — started/stopped alongside the drag lifecycle in `handleDrag` below. */
  const autoScroll = createNativeAutoScroll();

  /**
   * Translate x and y coordinates from pixels to grid units.
   * @param  {Number} top  Top position (relative to parent) in pixels.
   * @param  {Number} left Left position (relative to parent) in pixels.
   * @return {ICalcXy}     x and y in grid units.
   */
  const calcXY = (top: number, left: number): ICalcXy => {
    const colWidth = calcColWidth(containerWidth.value, margin.value[0], cols.value);

    let x = Math.round((left - margin.value[0]) / (colWidth + margin.value[0]));
    let y = Math.round((top - margin.value[1]) / (rowHeight.value + margin.value[1]));

    // Capping
    x = Math.max(Math.min(x, cols.value - innerW.value), 0);
    y = Math.max(Math.min(y, maxRows.value - innerH.value), 0);

    return {
      x,
      y,
    };
  };

  /**
   * The native drag engine's `dragstart`/`dragmove`/`dragend` handler — computes
   * the item's new pixel position (respecting RTL and `bounded`), converts
   * it to grid units via `calcXY`, and emits `MOVE`/`MOVED` plus the
   * eventBus `dragEvent` message `GridLayout` uses to cascade collisions.
   * Registered once per `GridItem` by `tryMakeDraggable`, not called
   * directly.
   */
  const handleDrag = (event: INativeDragEvent): void => {
    if(props.isStatic || !editModeEnabled.value) {
      return;
    }
    if(isResizing.value) {
      return;
    }

    const position = offsetXYFromParentOf(event);

    const { x, y } = position;

    const newPosition = {
      left: 0,
      top: 0,
    };

    switch(event.type) {
      case `dragstart`: {
        previousX.value = innerX.value;
        previousY.value = innerY.value;

        const tg = event.target as HTMLElement;
        const parentTg = tg.offsetParent as HTMLElement;
        const parentRect = parentTg.getBoundingClientRect();
        const clientRect = tg.getBoundingClientRect();

        const cLeft = clientRect.left / transformScale.value;
        const pLeft = parentRect.left / transformScale.value;
        const cRight = clientRect.right / transformScale.value;
        const pRight = parentRect.right / transformScale.value;
        const cTop = clientRect.top / transformScale.value;
        const pTop = parentRect.top / transformScale.value;

        if(renderRtl.value) {
          newPosition.left = (cRight - pRight) * -1;
        } else {
          newPosition.left = cLeft - pLeft;
        }
        newPosition.top = cTop - pTop;
        dragging.value = newPosition as IGridItemPosition;
        isDragging.value = true;
        if(props.autoScroll) {
          autoScroll.start(tg);
        }
        break;
      }
      case `dragend`: {
        if(!isDragging.value) {
          return;
        }

        // Bug fix (docs/REFACTORING.md #41): this used to re-derive the
        // final position from `event.target`'s live
        // `getBoundingClientRect()`, exactly like `dragstart` does — but
        // unlike `dragstart` (where nothing has moved yet, so a fresh
        // DOM measurement is trivially correct), by `dragend` there have
        // typically been many `dragmove` events already, each
        // synchronously updating `dragging.value` in JS. The browser
        // fires all of a fast mouse gesture's move/up events back to
        // back before yielding, but Vue's own re-render (turning the
        // updated `dragging.value` into an actual CSS transform on the
        // element) is asynchronous — queued, not immediate. Reading
        // getBoundingClientRect() at dragend could therefore capture
        // whatever position the DOM last happened to actually paint,
        // not the latest one `dragging.value` already holds, making a
        // fast/long drag land far short of where the pointer actually
        // ended up (confirmed directly: instrumenting handleDrag showed
        // every dragmove's accumulated delta was correct throughout,
        // but the final measured position only reflected an early
        // fraction of the total movement). `dragging.value` is already
        // the source of truth `dragmove` maintains — reusing it here
        // instead of a fresh, potentially-stale DOM read removes the
        // race entirely.
        newPosition.left = Number(dragging.value?.left);
        newPosition.top = Number(dragging.value?.top);
        dragging.value = undefined;
        isDragging.value = false;
        autoScroll.stop();
        break;
      }
      case `dragmove`: {
        const coreEvent = createCoreData(lastX.value, lastY.value, x, y);
        // Add rtl support
        if(renderRtl.value) {
          newPosition.left = Number(dragging.value?.left) - coreEvent.deltaX / transformScale.value;
        } else {
          newPosition.left = Number(dragging.value?.left) + coreEvent.deltaX / transformScale.value;
        }
        newPosition.top = Number(dragging.value?.top) + coreEvent.deltaY / transformScale.value;
        if(bounded.value) {
          const tg = event.target as HTMLElement;
          const parentTg = tg.offsetParent as HTMLElement;
          const bottomBoundary = parentTg.clientHeight - calcGridItemWH(props.h, rowHeight.value, margin.value[1]);
          newPosition.top = clamp(newPosition.top, 0, bottomBoundary);
          const colWidth = calcColWidth(containerWidth.value, margin.value[0], cols.value);
          const rightBoundary = containerWidth.value - calcGridItemWH(props.w, colWidth, margin.value[0]);
          newPosition.left = clamp(newPosition.left, 0, rightBoundary);
        }
        dragging.value = newPosition as IGridItemPosition;
        if(props.autoScroll) {
          autoScroll.update(event.clientX, event.clientY);
        }
        break;
      }
      default: {
        // Do nothing just to avoid linting complaints
      }
    }

    const pos: ICalcXy = calcXY(newPosition.top, newPosition.left);

    lastX.value = x;
    lastY.value = y;

    if(innerX.value !== pos.x || innerY.value !== pos.y) {
      emit(EGridItemEvent.MOVE, props.i, pos.x, pos.y);
    }

    if(event.type === `dragend` && (previousX.value !== innerX.value || previousY.value !== innerY.value)) {
      emit(EGridItemEvent.MOVED, props.i, pos.x, pos.y);
    }

    const data: IEventsData = {
      clientX: event.clientX,
      clientY: event.clientY,
      eventType: event.type,
      h: innerH.value,
      i: props.i,
      w: innerW.value,
      x: pos.x,
      y: pos.y,
    };
    eventBus.emit(`dragEvent`, data);
  };

  /**
   * Wires up the native draggable engine on first call (once
   * `gridItem.value` is a real, mounted element) — unlike interact.js's
   * own `.draggable(opts)`, which needed re-invoking on every relevant
   * prop change to reconfigure an existing `Interactable`, the native
   * engine reads `draggable`/`isStatic`/`dragAllowFrom`/`dragIgnoreFrom`
   * fresh on every `pointerdown` via its own `getOptions()` callback —
   * so nothing needs re-attaching when those change later. Still safe
   * to call repeatedly (from `GridItem.vue`'s watchers, exactly as
   * before): every call after the first is a no-op.
   */
  const tryMakeDraggable = (): void => {
    // Bug fix (docs/REFACTORING.md #38): gridItem starts as a plain `{}`
    // placeholder (`ref<HTMLElement>({} as HTMLElement)`), only becoming
    // the real DOM element once this component actually mounts. Several
    // watchers call tryMakeDraggable()/tryMakeResizable() reactively —
    // if one fires before (or during a brief window around) mount, the
    // native engine would be attached to that placeholder instead of a
    // real Element. Skipping the call entirely when the target isn't
    // mounted yet is safe: whichever watcher fires once it *is* mounted
    // picks the setup back up.
    if(!(gridItem.value instanceof HTMLElement)) {
      return;
    }

    if(nativeDraggable) {
      return;
    }

    nativeDraggable = createNativeDraggable(
      gridItem.value,
      () => ({
        allowFrom: props.dragAllowFrom,
        enabled: Boolean(draggable.value) && !props.isStatic,
        ignoreFrom: props.dragIgnoreFrom,
        activationDistance: props.dragActivationDistance,
      }),
      handleDrag,
    );
  };

  /** Tears down the native draggable engine's own listeners — called from `GridItem.vue`'s `onBeforeUnmount`. */
  const teardownDraggable = (): void => {
    nativeDraggable?.destroy();
    nativeDraggable = undefined;
  };

  /**
   * @returns
   * - `calcXY` — exposed because `GridItem.vue`'s own `defineExpose` re-exposes it publicly (see `calcXY` usage in `GridItem.vue`).
   * - `draggable` — the resolved draggable state; watched by `GridItem.vue` to re-run `tryMakeDraggable`.
   * - `dragging` — current pixel position while dragging; read by `GridItem.vue`'s `createStyle()`.
   * - `isDragging` — read by `classObj` and `createStyle()`.
   * - `teardownDraggable` — called from `GridItem.vue`'s `onBeforeUnmount`.
   * - `tryMakeDraggable` — called from `GridItem.vue`'s watchers.
   */
  return {
    calcXY,
    draggable,
    dragging,
    isDragging,
    teardownDraggable,
    tryMakeDraggable,
  };
}

import { ref, Ref, useSlots } from 'vue';
import { createNativeAutoScroll, createNativeResizable, RESIZE_EDGE_MAP } from '@/core/helpers/native-interaction';
import { createCoreData, offsetXYFromParentOf } from '@/core/helpers/draggable-utils';
import { calcColWidth } from '@/core/griditem/helpers/grid-item-calculate-helper';
import { EGridItemEvent } from '@/core/griditem/enums/EGridItemEvents';
import { ICalcWh, IGridItemPosition, IInteractEdges } from '@/core/griditem/interfaces/grid-item.interfaces';
import { IEventsData } from '@/core/common/interfaces/event-bus.interfaces';
import { IGridItemComposableContext } from './grid-item-composable-context';

/**
 * A `resizestart`/`resizemove`/`resizeend` event, as `handleResize` below
 * actually receives and uses it: the three fields `offsetXYFromParentOf`
 * reads (`clientX`/`clientY`/`target`) plus `edges` — the resize-handle
 * combination active for this gesture (see
 * `@/core/helpers/native-interaction.ts`'s `RESIZE_EDGE_MAP`).
 */
type TResizeEvent = {
  type: `resizestart` | `resizemove` | `resizeend`;
  target: HTMLElement;
  clientX: number;
  clientY: number;
  edges: IInteractEdges;
};

/**
 * Encapsulates GridItem's resizing behavior: the native pointer-driven
 * resize engine's wiring (including native aspect-ratio preservation),
 * pixel-to-grid-unit size math, the resize lifecycle
 * (resizestart/resizemove/resizeend), and
 * `autoSize()` — the "resize when slot content changes" feature, which is
 * really just another way of arriving at the same resize-completion flow.
 *
 * Extracted from GridItem.vue as part of the Phase 2 structural cleanup —
 * see docs/REFACTORING.md's "GridItem.vue is doing too much" section and
 * docs/ARCHITECTURE.md for how this fits alongside `useGridItemDrag`.
 */
/** Return shape of {@link useGridItemResize}. */
export interface IUseGridItemResizeReturn {
  autoSize: () => void;
  calcPosition: (x: number, y: number, w: number, h: number) => IGridItemPosition;
  calcWH: (height: number, width: number, autoSizeFlag?: boolean) => ICalcWh;
  isResizing: Ref<boolean>;
  resizable: Ref<boolean | null>;
  resizing: Ref<IGridItemPosition | undefined>;
  setupAutoHeight: () => void;
  teardownAutoHeight: () => void;
  teardownResizable: () => void;
  tryMakeResizable: () => void;
}

export function useGridItemResize(ctx: IGridItemComposableContext): IUseGridItemResizeReturn {
  const {
    autoHeightWrapper,
    cols,
    containerWidth,
    editModeEnabled,
    emit,
    eventBus,
    gridItem,
    innerH,
    innerW,
    innerX,
    innerY,
    margin,
    maxRows,
    props,
    renderRtl,
    resizeHandleRefs,
    resizeHandles,
    rowHeight,
    transformScale,
  } = ctx;

  const slots = useSlots();

  /** `null` until `GridItem`'s `onMounted` resolves it from the `isResizable` prop or the parent layout's default. */
  const resizable = ref<boolean | null>(null);
  /** Whether a resize is currently in progress — drives the `resizing` class and blocks `useGridItemDrag`'s `handleDrag` from running concurrently. */
  const isResizing = ref(false);
  /** Current pixel position+size while resizing; `undefined` when not resizing. Tracks `left`/`right`/`top` too, not just `width`/`height`, so left/top-edge resizes can move the item's anchor point live (see `handleResize`). */
  const resizing = ref<IGridItemPosition | undefined>(undefined);
  /** Previous tick's pointer x position, `NaN` before the first `resizemove`. */
  const lastW = ref(NaN);
  /** Previous tick's pointer y position, `NaN` before the first `resizemove`. */
  const lastH = ref(NaN);
  /** Grid-unit width at resize-start, used to detect whether a resize actually changed the item's size (for the `RESIZED` event). */
  const previousW = ref<number | undefined>(undefined);
  /** Grid-unit height at resize-start. */
  const previousH = ref<number | undefined>(undefined);
  /** Starting pixel width/height ratio, captured at `resizestart` — used by `preserveAspectRatio` to derive one dimension from the other during `resizemove`. `undefined` when not resizing or the starting height was 0. */
  const aspectRatio = ref<number | undefined>(undefined);
  /** Backing the `autoScroll` prop — started/stopped alongside the resize lifecycle in `handleResize` below. */
  const autoScroll = createNativeAutoScroll();
  /** The native resize engine's own cleanup handle, once created — `undefined` until `tryMakeResizable` first runs against a real, mounted element. */
  let nativeResizable: { destroy: () => void } | undefined;

  /** Which edges are being dragged during the current resize, as reported by the native resize engine's `resizestart` event (see the handle each of the 8 resize-hint spans is wired to). */
  let edges: IInteractEdges = {
    bottom: false,
    left: false,
    right: false,
    top: false,
  };

  /**
   * Convert grid-unit x/y/w/h into pixel position + size, respecting RTL.
   * Shared with GridItem's own `createStyle()` for rendering, which is why
   * it's returned rather than kept private like `handleResize`.
   */
  const calcPosition = (x: number, y: number, w: number, h: number): IGridItemPosition => {
    const colWidth = calcColWidth(containerWidth.value, margin.value[0], cols.value);

    let out;
    if(renderRtl.value) {
      out = {
        height: h === Infinity ? h : Math.round(rowHeight.value * h + Math.max(0, h - 1) * margin.value[1]),
        right: Math.round(colWidth * x + (x + 1) * margin.value[0]),
        top: Math.round(rowHeight.value * y + (y + 1) * margin.value[1]),
        width: w === Infinity ? w : Math.round(colWidth * w + Math.max(0, w - 1) * margin.value[0]),
      };
    } else {
      out = {
        height: h === Infinity ? h : Math.round(rowHeight.value * h + Math.max(0, h - 1) * margin.value[1]),
        left: Math.round(colWidth * x + (x + 1) * margin.value[0]),
        top: Math.round(rowHeight.value * y + (y + 1) * margin.value[1]),
        width: w === Infinity ? w : Math.round(colWidth * w + Math.max(0, w - 1) * margin.value[0]),
      };
    }

    return out;
  };

  /**
   * Given a height and width in pixel values, calculate grid units.
   * @param  {Number} height Height in pixels.
   * @param  {Number} width  Width in pixels.
   * @param  {Boolean} autoSizeFlag  function autoSize identifier.
   * @return {ICalcWh} w, h as grid units.
   */
  const calcWH = (height: number, width: number, autoSizeFlag: boolean = false): ICalcWh => {
    const colWidth = calcColWidth(containerWidth.value, margin.value[0], cols.value);

    let w = Math.round((width + margin.value[0]) / (colWidth + margin.value[0]));
    let h;
    if(!autoSizeFlag) {
      h = Math.round((height + margin.value[1]) / (rowHeight.value + margin.value[1]));
    } else {
      h = Math.ceil((height + margin.value[1]) / (rowHeight.value + margin.value[1]));
    }

    // Capping
    w = Math.max(Math.min(w, cols.value - innerX.value), 0);
    h = Math.max(Math.min(h, maxRows.value - innerY.value), 0);
    return {
      h,
      w,
    };
  };

  /**
   * Convert a new left-edge pixel position to a grid-unit x, capped so the
   * item (at its new width `newW`) can't be pushed past the right edge of
   * the grid. The left/top-edge counterpart to `calcXY` in
   * `useGridItemDrag.ts` — not shared with it because the capping bound
   * here depends on the *new* size being resized to, not the item's
   * current (pre-resize) size, which is what `calcXY` assumes.
   */
  const pixelsToGridX = (leftPx: number, newW: number): number => {
    const colWidth = calcColWidth(containerWidth.value, margin.value[0], cols.value);
    let gridX = Math.round((leftPx - margin.value[0]) / (colWidth + margin.value[0]));
    gridX = Math.max(Math.min(gridX, cols.value - newW), 0);
    return gridX;
  };

  /** Top-edge counterpart to `pixelsToGridX`. */
  const pixelsToGridY = (topPx: number, newH: number): number => {
    let gridY = Math.round((topPx - margin.value[1]) / (rowHeight.value + margin.value[1]));
    gridY = Math.max(Math.min(gridY, maxRows.value - newH), 0);
    return gridY;
  };

  /**
   * The native resize engine's `resizestart`/`resizemove`/`resizeend` handler —
   * computes the item's new pixel size (and, for left/top-edge resizes,
   * new position — see docs/REFACTORING.md's resize-direction note)
   * based on which edge(s) are being dragged, converts it to grid units
   * via `calcWH`/`pixelsToGridX`/`pixelsToGridY`, clamps to
   * `minW`/`maxW`/`minH`/`maxH`, and emits `RESIZE`/`RESIZED` plus the
   * eventBus `resizeEvent` message. Registered once per `GridItem` by
   * `tryMakeResizable`, not called directly.
   */
  const handleResize = (event: TResizeEvent): void => {
    // Confirmed unreachable through any real interaction path, not
    // assumed: the isResizable side of this guard only matters when
    // enableEditMode is false, but resizableAndNotStatic (GridItem.vue's
    // own gate on rendering the 8 resize-hint spans, and therefore on
    // whether tryMakeResizable() ever has any handleEls to wire up at
    // all) is already false in that same state — so the native resize
    // engine's own handler is never even registered, and there's no way
    // to reach handleResize() at all when this specific branch would
    // matter. A fresh test dispatching directly via the native-handler
    // backdoor in this state confirmed the handler itself doesn't exist
    // to call, rather than confirming this guard's own behavior.
    /* v8 ignore next 3 -- see the comment above: unreachable since the native resize engine is never wired up at all in the one state (enableEditMode false) where this branch would matter. */
    if(props.isStatic || (!editModeEnabled.value && props.isResizable)) {
      return;
    }
    const position = offsetXYFromParentOf(event);

    const { x, y } = position;

    const newSize: { height: number; horizontal?: number; top?: number; width: number } = {
      height: 0,
      width: 0,
    };

    let pos: (IGridItemPosition | ICalcWh) & { h?: number; w?: number };

    switch(event.type) {
      case `resizestart`: {
        // Note: previously re-called tryMakeResizable() here to refresh
        // interact.js's own config before handling the gesture. Not
        // needed under the native engine's "configure once, read live
        // state per-gesture" model (see tryMakeResizable's own doc
        // comment) — nativeResizable is already attached, and
        // getOptions() reads current prop values fresh on every
        // pointerdown regardless.
        emit(EGridItemEvent.RESIZE, props.i, innerH.value, innerW.value, innerH.value, innerW.value);
        previousW.value = innerW.value;
        previousH.value = innerH.value;
        pos = calcPosition(innerX.value, innerY.value, innerW.value, innerH.value);
        // Bug fix: the code shared by all three event types below this
        // switch statement (`pos = calcWH(newSize.height, newSize.width)`
        // onward) recomputes `pos` from `newSize`, but `newSize` is only
        // ever populated by the resizemove/resizeend cases — for
        // resizestart it's still its initial `{ height: 0, width: 0 }`.
        // `calcWH(0, 0)` producing a near-zero size, then clamped up to
        // the library's own 1x1 floor, silently overwrote this case's
        // own correct `pos` (and, from there, the eventBus payload, and
        // from there `GridLayout`'s own `l.w`/`l.h`) with `{ h: 1, w: 1 }`
        // on every single `resizestart` — before anything had actually
        // resized. Nothing user-visible caught this directly (the
        // *rendered* size stays correct, driven by CSS already
        // reflecting the real size from the previous render) — it only
        // surfaced once something else read the corrupted `props.layout`
        // value later, e.g. multiSelect's own group-resize snapshot,
        // silently applying a wrong delta to every other selected item.
        // Emitting this case's own, already-correct eventBus message
        // directly and returning early — rather than trying to guard
        // the shared code against running for this event type instead —
        // keeps resizestart's own values as the single source of truth
        // for what it emits, with no risk of the shared recomputation
        // touching them at all.
        resizing.value = { ...pos };
        isResizing.value = true;
        ({ edges } = event);
        aspectRatio.value = pos.height > 0 ? pos.width / pos.height : undefined;
        if(props.autoScroll) {
          autoScroll.start(event.target);
        }
        // The shared code below this switch statement (which this case
        // returns early to avoid — see the comment above) is also where
        // `lastW`/`lastH` get initialized to the starting pointer
        // position, which `resizemove`'s own delta calculation
        // (`createCoreData(lastW.value, lastH.value, x, y)`) depends on
        // having a real value rather than stale/initial ones. Setting
        // them here too, not just skipping past where they used to be
        // set as a side effect of the (buggy) fall-through.
        lastW.value = x;
        lastH.value = y;
        eventBus.emit(`resizeEvent`, {
          eventType: event.type,
          h: innerH.value,
          i: props.i,
          w: innerW.value,
          x: innerX.value,
          y: innerY.value,
        });
        return;
      }
      case `resizemove`: {
        const coreEvent = createCoreData(lastW.value, lastH.value, x, y);
        const dx = coreEvent.deltaX / transformScale.value;
        const dy = coreEvent.deltaY / transformScale.value;

        // "horizontal" is whichever anchor calcPosition used for this
        // render direction — `left` in LTR, `right` in RTL (see the
        // edges.right/edges.left handling below for how each one gets
        // updated correctly per direction — fixed in docs/REFACTORING.md
        // #53, verified with real click-drag browser tests in both
        // directions, not just reasoned through).
        const prevHorizontal = Number(renderRtl.value ? resizing.value?.right : resizing.value?.left);
        const prevTop = Number(resizing.value?.top);
        const prevWidth = Number(resizing.value?.width);
        const prevHeight = Number(resizing.value?.height);

        newSize.width = prevWidth;
        newSize.height = prevHeight;
        newSize.horizontal = prevHorizontal;
        newSize.top = prevTop;

        // Each edge is handled independently (rather than one branch per
        // edge combination) so every single-edge and every corner
        // combination — including the diagonals — falls out of the same
        // four lines instead of needing eight near-duplicate branches.
        //
        // `edges.left`/`edges.right` describe the *physical* edge being
        // dragged — screen-space, unaffected by RTL — but which one of
        // them should also move the `horizontal` anchor depends on
        // render direction, since dragging an edge only moves the anchor
        // when that edge *is* the anchor. In LTR, `horizontal` means
        // `left`: dragging the right edge grows/shrinks width with the
        // left edge fixed (anchor untouched, correct below); dragging
        // the left edge is what moves the anchor itself. In RTL,
        // `horizontal` means `right` instead — so it's now the *right*
        // edge whose drag moves the anchor, and the left edge that
        // leaves it alone. Previously this was hardcoded to the LTR
        // case regardless of `renderRtl`, so RTL resize dragged the
        // wrong edge fixed in place (see docs/REFACTORING.md #53).
        if(edges.right) {
          newSize.width = prevWidth + dx;
          if(renderRtl.value) {
            newSize.horizontal = prevHorizontal - dx;
          }
        }
        if(edges.left) {
          newSize.width = prevWidth - dx;
          if(!renderRtl.value) {
            newSize.horizontal = prevHorizontal + dx;
          }
        }
        if(edges.bottom) {
          newSize.height = prevHeight + dy;
        }
        if(edges.top) {
          newSize.height = prevHeight - dy;
          newSize.top = prevTop + dy;
        }

        // preserveAspectRatio — native replacement for interact.js's
        // `aspectRatio` modifier (see docs/REFACTORING.md). Derives
        // whichever dimension isn't directly driven by the edge(s) in
        // this gesture from the one that is, using the ratio captured
        // at resizestart. A single horizontal-only or vertical-only
        // edge derives the other dimension outright (no anchor
        // adjustment needed, since the undriven dimension's own anchor
        // was never touched above); a corner (both a horizontal and a
        // vertical edge active) derives height from width and, if the
        // top edge is part of this gesture, adjusts `top` by exactly
        // the resulting height delta — the same anchor-compensation
        // `edges.top` already does for a direct height change above,
        // just applied to the derived one instead.
        if(props.preserveAspectRatio && aspectRatio.value) {
          const drivingWidth = edges.left || edges.right;
          const drivingHeight = edges.top || edges.bottom;
          if(drivingWidth && !drivingHeight) {
            newSize.height = newSize.width / aspectRatio.value;
          } else if(drivingHeight && !drivingWidth) {
            newSize.width = newSize.height * aspectRatio.value;
          } else if(drivingWidth && drivingHeight) {
            const derivedHeight = newSize.width / aspectRatio.value;
            if(edges.top) {
              newSize.top = prevTop + (prevHeight - derivedHeight);
            }
            newSize.height = derivedHeight;
          }
        }

        if(props.autoScroll) {
          autoScroll.update(event.clientX, event.clientY);
        }

        resizing.value = {
          ...resizing.value,
          height: newSize.height,
          top: newSize.top,
          width: newSize.width,
          ...(renderRtl.value ? { right: newSize.horizontal } : { left: newSize.horizontal }),
        } as IGridItemPosition;
        break;
      }
      case `resizeend`: {
        // Bug fix (docs/REFACTORING.md #41, same class as dragend's):
        // this used to recompute `newSize` via `calcPosition(innerX.value,
        // innerY.value, innerW.value, innerH.value)` — but `innerW`/
        // `innerH` are the grid item's *pre-resize* dimensions, only
        // ever updated later via the emit()/eventBus round trip through
        // the parent layout, which hasn't happened yet within this same
        // synchronous resize gesture. Every `resizemove` had already been
        // correctly accumulating the live pixel size into
        // `resizing.value` — recomputing from `innerW`/`innerH` here
        // instead discarded all of that and used the size the item had
        // *before* the resize even started, which is exactly why
        // resizing appeared to grow the item by nothing at all.
        newSize.width = Number(resizing.value?.width);
        newSize.height = Number(resizing.value?.height);
        newSize.top = Number(resizing.value?.top);
        newSize.horizontal = Number(renderRtl.value ? resizing.value?.right : resizing.value?.left);
        resizing.value = undefined;
        isResizing.value = false;
        aspectRatio.value = undefined;
        autoScroll.stop();
        break;
      }
      default: {
        // Do nothing just to avoid linting complaints
      }
    }

    // Get new WH
    pos = calcWH(newSize.height, newSize.width);
    // minW/maxW/minH/maxH all have withDefaults() defaults (1/Infinity), so
    // they're guaranteed present at runtime — the `!` here is only needed
    // because that guarantee lives in GridItem.vue's withDefaults() call,
    // which TypeScript can't see through once props cross a module boundary.
    if(pos.w < props.minW!) {
      pos.w = props.minW!;
    }
    if(pos.w > props.maxW!) {
      pos.w = props.maxW!;
    }
    if(pos.h < props.minH!) {
      pos.h = props.minH!;
    }
    if(pos.h > props.maxH!) {
      pos.h = props.maxH!;
    }

    if(pos.h < 1) {
      pos.h = 1;
    }
    if(pos.w < 1) {
      pos.w = 1;
    }

    // For left/top-edge resizes (right-edge in RTL — see the
    // edges.right/edges.left handling above, and docs/REFACTORING.md
    // #53), derive the new grid-unit position too — capped against the
    // *new* w/h computed just above. The non-anchor-edge-only resizes
    // never touch position, so this leaves x/y at their current values
    // in that case.
    let newX = innerX.value;
    let newY = innerY.value;
    const horizontalAnchorEdge = renderRtl.value ? edges.right : edges.left;
    if(horizontalAnchorEdge && newSize.horizontal !== undefined) {
      // pixelsToGridX's formula is the same regardless of which CSS
      // property (`left` or `right`) newSize.horizontal actually
      // represents — calcPosition computes both the same way
      // (`colWidth * x + (x + 1) * margin`), just assigned to a
      // different property name depending on renderRtl — so no
      // direction-specific math is needed here beyond picking the right
      // edge to trigger on above.
      newX = pixelsToGridX(newSize.horizontal, pos.w);
    }
    if(edges.top && newSize.top !== undefined) {
      newY = pixelsToGridY(newSize.top, pos.h);
    }

    lastW.value = x;
    lastH.value = y;

    if(innerW.value !== pos.w || innerH.value !== pos.h) {
      emit(EGridItemEvent.RESIZE, props.i, pos.h, pos.w, newSize.height, newSize.width);
    }
    if(event.type === `resizeend` && (previousW.value !== innerW.value || previousH.value !== innerH.value)) {
      emit(EGridItemEvent.RESIZED, props.i, pos.h, pos.w, newSize.height, newSize.width);
    }

    const data: IEventsData = {
      eventType: event.type,
      h: pos.h,
      i: props.i,
      w: pos.w,
      x: newX,
      y: newY,
    };

    eventBus.emit(`resizeEvent`, data);
  };

  /**
   * Wires up the native resize engine on first call (once
   * `gridItem.value` is a real, mounted element and the 8 resize-hint
   * spans have their own template refs populated) — same "configure
   * once, read live state per-gesture" model as
   * `useGridItemDrag.ts`'s `tryMakeDraggable`. `minW`/`maxW`/`minH`/
   * `maxH` clamping during the gesture itself is intentionally not
   * reimplemented from interact.js's own `restrictSize` here — the
   * clamps inside `handleResize` below (and `useGridItemKeyboard.ts`'s
   * own) are already the actual source of truth; interact.js's
   * equivalent was already redundant, not load-bearing.
   */
  const tryMakeResizable = (): void => {
    // See the matching guard + comment in useGridItemDrag.ts's
    // tryMakeDraggable() (docs/REFACTORING.md #38) — same bug, same fix.
    // Confirmed unreachable through any normal test flow, not assumed:
    // gridItem isn't exposed via defineExpose, and exposing an internal
    // DOM ref solely to manufacture coverage for an already-fixed bug
    // would be adding public API surface for the wrong reason (see
    // docs/REFACTORING.md #70's own "genuinely hard-to-cover guards"
    // note for the identical gridItem check in useGridItemDrag.ts).
    /* v8 ignore next 3 -- see the comment above: unreachable without exposing gridItem via defineExpose solely to manufacture coverage. */
    if(!(gridItem.value instanceof HTMLElement)) {
      return;
    }

    if(nativeResizable) {
      return;
    }

    const handleEls: Partial<Record<keyof typeof RESIZE_EDGE_MAP, HTMLElement>> = {};
    for(const edgeKey of Object.keys(RESIZE_EDGE_MAP) as (keyof typeof RESIZE_EDGE_MAP)[]) {
      // Only wire up handles actually present in the resolved
      // `resizeHandles` set (GridItem's own prop, or GridLayout's
      // default when it's null) — restricts which edges/corners the
      // native resize engine listens on, instead of always all 8.
      if(!resizeHandles.value.includes(edgeKey)) {
        continue;
      }
      const handleEl = resizeHandleRefs[edgeKey]?.value;
      if(handleEl) {
        handleEls[edgeKey] = handleEl;
      }
    }

    // Bug fix: the 8 resize-hint spans are `v-if`-gated on the resolved
    // `resizable` state, which this same `onMounted` sets *synchronously*
    // just before first calling this function — but Vue's own DOM
    // update from that change is asynchronous (batched to the next
    // tick), so the very first call here could run before the spans
    // actually exist yet, finding zero handles. Since `nativeResizable`
    // being set is what permanently guards against re-attaching (see
    // the comment on tryMakeDraggable's own version of this pattern),
    // locking it in on that first, handle-less call would leave resize
    // wired up to nothing for the rest of this GridItem's lifetime —
    // not just delayed, silently broken. Only committing once at least
    // one handle was actually found lets whichever later call (from the
    // same watchers that already call this reactively) picks the setup
    // back up once the DOM has caught up.
    if(Object.keys(handleEls).length === 0) {
      return;
    }

    nativeResizable = createNativeResizable(
      gridItem.value,
      handleEls,
      () => ({ enabled: Boolean(resizable.value) && !props.isStatic, ignoreFrom: props.resizeIgnoreFrom }),
      handleResize,
    );
  };

  /** Tears down the native resize engine's own listeners — called from `GridItem.vue`'s `onBeforeUnmount`. */
  const teardownResizable = (): void => {
    nativeResizable?.destroy();
    nativeResizable = undefined;
  };

  /**
   * Resize the item to fit its slot content's measured size — the
   * "GridItem automatically resizes when content changes" feature.
   *
   * See docs/REFACTORING.md #12: `slots.default()` here returns freshly
   * created VNodes, not the ones the renderer actually mounted, so `.elm`
   * is not reliably available. This bails out as a no-op rather than
   * throwing when that's the case; the underlying measurement approach
   * still needs a template-ref-based rewrite to be fully reliable.
   */
  function autoSize(): void {
    previousW.value = innerW.value;
    previousH.value = innerH.value;

    // Prefers autoHeightWrapper (a real template ref, only populated
    // when the autoHeight prop is true) over slots.default()[0]?.elm —
    // confirmed directly that the latter doesn't reliably tie back to
    // real DOM even when read from within this component's own
    // lifecycle (an async ResizeObserver callback, in autoHeight's
    // case), not just when autoSize() is invoked externally as
    // originally documented in finding #12. Falls back to the
    // slots-based lookup for a manually-invoked autoSize() call without
    // autoHeight enabled at all, where no wrapper ref exists to prefer.
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    const slotElement = autoHeightWrapper.value ?? slots?.default?.()[0]?.elm;
    if(!slotElement || typeof slotElement.getBoundingClientRect !== `function`) {
      return;
    }

    const newSize = slotElement.getBoundingClientRect();
    const pos = calcWH(newSize.height, newSize.width, true);
    if(props.minW) {
      if(pos.w < props.minW) {
        pos.w = props.minW;
      }
    }

    if(props.maxW) {
      if(pos.w > props.maxW) {
        pos.w = props.maxW;
      }
    }

    if(props.minH) {
      if(pos.h < props.minH) {
        pos.h = props.minH;
      }
    }

    if(props.maxH) {
      if(pos.h > props.maxH) {
        pos.h = props.maxH;
      }
    }

    // Bug fix (docs/REFACTORING.md #70): calcWH's own autoSizeFlag height
    // conversion uses Math.ceil, which rounds any non-negative height up
    // to at least 1 grid unit on its own — confirmed, not assumed, that
    // this makes the floor check below genuinely unreachable for height
    // specifically (never negative from a real getBoundingClientRect()),
    // unlike the width side (Math.round, which can round down to 0).
    // Left as a documented, understood gap rather than forced with a
    // manufactured negative-height double.
    /* v8 ignore next 3 -- see the comment above: Math.ceil already floors height to >=1 whenever it's non-negative, which a real getBoundingClientRect() always is. */
    if(pos.h < 1) {
      pos.h = 1;
    }
    if(pos.w < 1) {
      pos.w = 1;
    }

    if(innerW.value !== pos.w || innerH.value !== pos.h) {
      emit(EGridItemEvent.RESIZE, props.i, pos.h, pos.w, newSize.height, newSize.width);
    }

    if(previousW.value !== pos.w || previousH.value !== pos.h) {
      emit(EGridItemEvent.RESIZED, props.i, pos.h, pos.w, newSize.height, newSize.width);

      const data: IEventsData = {
        eventType: `resizeend`,
        h: pos.h,
        i: props.i,
        w: pos.w,
        x: innerX.value,
        y: innerY.value,
      };
      eventBus.emit(`resizeEvent`, data);
    }
  }

  /**
   * Backing implementation for the `autoHeight` prop — a `ResizeObserver`
   * on `autoHeightWrapper` (a template ref, only rendered/populated when
   * `autoHeight` is true), calling `autoSize()` whenever it actually
   * changes size. Deliberately not `slots.default()[0]?.elm`, the way
   * `autoSize()` itself reads the slot content when manually invoked —
   * confirmed directly (not assumed) that this doesn't reliably tie back
   * to real DOM even when called from `onMounted`, not just when invoked
   * externally as originally documented in finding #12: Vue's own
   * "Slot 'default' invoked outside of the render function" warning
   * fires either way, since `onMounted`'s callback runs outside Vue's
   * own render-function call context regardless of which lifecycle
   * point it's called from. A real template ref sidesteps the problem
   * entirely rather than working around it.
   */
  let autoHeightObserver: ResizeObserver | undefined;

  const setupAutoHeight = (): void => {
    if(!props.autoHeight || typeof ResizeObserver === `undefined` || !autoHeightWrapper.value) {
      return;
    }
    autoHeightObserver = new ResizeObserver(() => {
      autoSize();
    });
    autoHeightObserver.observe(autoHeightWrapper.value);
  };

  const teardownAutoHeight = (): void => {
    autoHeightObserver?.disconnect();
    autoHeightObserver = undefined;
  };

  /**
   * @returns
   * - `autoSize` — exposed because `GridItem.vue`'s own `defineExpose` re-exposes it publicly.
   * - `calcPosition` — used by `GridItem.vue`'s `createStyle()` for rendering.
   * - `calcWH` — used by `GridItem.vue`'s `autoSize` caller context; kept alongside `autoSize` for symmetry.
   * - `isResizing` — read by `classObj`/`createStyle()`, and passed into `useGridItemDrag`'s context.
   * - `resizable` — the resolved resizable state; watched by `GridItem.vue` to re-run `tryMakeResizable`.
   * - `resizing` — current pixel position+size while resizing; read by `createStyle()`.
   * - `teardownResizable` — called from `GridItem.vue`'s `onBeforeUnmount`.
   * - `tryMakeResizable` — called from `GridItem.vue`'s watchers.
   */
  return {
    autoSize,
    calcPosition,
    calcWH,
    isResizing,
    resizable,
    resizing,
    setupAutoHeight,
    teardownAutoHeight,
    teardownResizable,
    tryMakeResizable,
  };
}

import { nextTick, Ref } from 'vue';
import { ILayoutItem, TLayout } from '@/components/Grid/layout-definition';
import { IGridLayoutProps } from '../grid-layout-props.interface';
import { getCompactor } from '@/core/gridlayout/helpers/compactor';
import { ECompactType } from '@/core/gridlayout/enums/ECompactType';
import { findCrossGridZoneAt, registerCrossGridZone } from '@/core/gridlayout/helpers/cross-grid-registry';
import { ICrossGridZone } from '@/core/gridlayout/interfaces/cross-grid.interfaces';
import { EGridLayoutEvent } from '@/core/gridlayout/enums/EGridLayoutEvents';
import { TGridLayoutEventBus } from '@/core/gridlayout/interfaces/layout-data.interface';
import { findFirstFitSlot } from '@/core/gridlayout/helpers/bin-pack-helper';

/** Dependencies `useCrossGridDrag` needs from `GridLayout.vue`. */
export interface IUseCrossGridDragContext {
  props: IGridLayoutProps;
  /**
   * `GridLayout`'s own `defineEmits`-generated emit — its real type is a
   * *union of call signatures*, one per declared event, each with its
   * own specific payload types (not a single, nameable function shape).
   * Tried narrowing this to `(event: EGridLayoutEvent, ...args:
   * unknown[]) => void` and separately to `(event: string, ...args:
   * unknown[]) => void` — both broke the actual assignment at every
   * real call site (`GridLayout.vue` passing its own `emit` in), since
   * Vue's overloaded type only accepts specific literal event names per
   * overload, not the broader parameter type either alternative
   * promised. `any` here is a deliberate, checked exception, not an
   * oversight — every real call site (see below) still passes a real
   * `EGridLayoutEvent` value in practice.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  emit: (...args: any[]) => void;
  eventBus: TGridLayoutEventBus;
  /** `GridLayout`'s own root element ref — used for this grid's own `getRect()` in the cross-grid registry. */
  refsLayout: Ref<HTMLElement>;
  isDragging: Ref<boolean>;
  originalLayout: Ref<TLayout | undefined>;
  updateHeight: () => void;
}

/**
 * Encapsulates `allowCrossGridDrag`: registering this grid into the
 * shared cross-grid registry (`core/gridlayout/helpers/cross-grid-registry.ts`),
 * tracking which item (if any) is currently being dragged with
 * cross-grid dropping possible, and the accept/reject decision at
 * `dragend`.
 *
 * Extracted from `GridLayout.vue` as part of the structural cleanup
 * flagged in `docs/REFACTORING.md`'s Structural section — see
 * `docs/ARCHITECTURE.md` for the full design this composable
 * implements, and finding #68 there for the extraction itself. Kept
 * deliberately un-reactive internally (`crossGridDraggedId`,
 * `unregisterCrossGridZone` are plain variables, not refs) — nothing
 * here needs a reactive read/write, it's just state read once at
 * `dragend`, matching the reasoning already documented for these same
 * variables before the extraction (see finding #35).
 */
/** Return shape of {@link useCrossGridDrag}. */
export interface IUseCrossGridDragReturn {
  handleDragEnd: (
    id: string | number,
    clientX: number | undefined,
    clientY: number | undefined,
    currentItem: ILayoutItem,
  ) => boolean;
  handleDragStart: (id: string | number) => void;
  setCrossGridDragEnabled: (enabled: boolean) => void;
  teardown: () => void;
}

export function useCrossGridDrag(ctx: IUseCrossGridDragContext): IUseCrossGridDragReturn {
  const { props, emit, eventBus, refsLayout, isDragging, originalLayout, updateHeight } = ctx;

  let crossGridDraggedId: string | number | null = null;
  let unregisterCrossGridZone: (() => void) | undefined;

  /** This grid's own `getRect`/`acceptDrop`/`rejectDrop` implementation, registered into the shared cross-grid registry when `allowCrossGridDrag` is true. */
  const crossGridZone: ICrossGridZone = {
    acceptDrop: (item, sourceLayoutId) => {
      // Bug fix: this used to place the dropped item at a hardcoded
      // `{ x: 0, y: 999 }` and rely on the subsequent vertical-compact
      // call to settle it into place — the same "place far below, let
      // compaction pull it up" anti-pattern `findFirstFitSlot`'s own
      // doc comment specifically calls out as broken: plain vertical
      // compaction only ever moves an item straight up *within its own
      // x range*, it never searches other columns, and it can't jump
      // over a static item blocking that column to reach a gap further
      // up. Reported directly: a static item sitting below an actual
      // gap (e.g. `A` at y:0, a static item at y:4, gap at y:2) meant a
      // dropped item landed at y:6 — pushed down against the static
      // item's own bottom edge — instead of in the gap at y:2, since
      // straight-up movement from y:999 hit the static item first and
      // stopped there, never able to continue past it. `findFirstFitSlot`
      // does a real first-fit bin-pack instead — row by row, column by
      // column — so it finds the gap directly regardless of what's
      // sitting below it.
      const slot = findFirstFitSlot(props.layout, props.colNum as number, item.w, item.h);
      const droppedItem: ILayoutItem = { ...item, x: slot.x, y: slot.y };
      // Mutates props.layout in place (push), matching how every other
      // in-place layout change in this file works (compactLayout/
      // moveElement mutate existing items' x/y directly) — a fresh array
      // via spread/concat here would only reach a real v-model consumer
      // through the `update:layout` emit below, not the same array
      // reference this component (and anything already holding a
      // reference to it, e.g. a test) is reading from.
      props.layout.push(droppedItem);
      emit(EGridLayoutEvent.LAYOUT_UPDATE, props.layout);
      getCompactor(props.compactType! as ECompactType).compact(props.layout, props.colNum as number, {
        compactType: props.compactType! as ECompactType,
      });
      eventBus.emit(`compact`);
      updateHeight();
      emit(EGridLayoutEvent.CROSS_GRID_ITEM_DROPPED, { item: droppedItem, sourceLayoutId });
    },
    getRect: () => (refsLayout.value instanceof HTMLElement ? refsLayout.value.getBoundingClientRect() : null),
    isExternalDropDisabled: () => props.disableExternalDrop as boolean,
    get layoutId() {
      return props.layoutId as string;
    },
    rejectDrop: (itemId, sourceLayoutId) => {
      emit(EGridLayoutEvent.CROSS_GRID_DROP_REJECTED, { itemId, sourceLayoutId });
    },
  };

  /**
   * Registers/unregisters this grid's `crossGridZone` with the shared
   * registry — called once at mount with the initial `allowCrossGridDrag`
   * value, and again whenever that prop changes reactively.
   */
  const setCrossGridDragEnabled = (enabled: boolean): void => {
    if(enabled && !unregisterCrossGridZone) {
      unregisterCrossGridZone = registerCrossGridZone(crossGridZone);
    } else if(!enabled && unregisterCrossGridZone) {
      unregisterCrossGridZone();
      unregisterCrossGridZone = undefined;
    }
  };

  /** Unregisters this grid on unmount — a no-op if it was never registered (`allowCrossGridDrag` was never true). */
  const teardown = (): void => {
    unregisterCrossGridZone?.();
  };

  /** Called from `dragEvent()`'s `EDragEvent.DRAG_START` case. Records which item is being dragged, if cross-grid dragging is enabled. */
  const handleDragStart = (id: string | number): void => {
    if(props.allowCrossGridDrag) {
      crossGridDraggedId = id;
    }
  };

  /**
   * Called from `dragEvent()`'s `EDragEvent.DRAG_END` case, before its
   * own normal end-of-drag handling. Returns `true` if the drop was
   * accepted by another grid — in which case this function already
   * performed every side effect the accept path needs (removing the
   * item from `props.layout`, compaction, the various emits,
   * `isDragging`/`originalLayout` updates), and the caller should
   * `return` immediately rather than also running its own normal
   * end-of-drag logic, since the item no longer belongs to this grid's
   * layout at all. Returns `false` for every other case (cross-grid
   * dragging isn't enabled, no drag was in progress, no target zone
   * found at the drop point, or the target rejected it) — the caller
   * should continue with its own normal end-of-drag handling exactly as
   * if this function didn't exist.
   */
  const handleDragEnd = (
    id: string | number,
    clientX: number | undefined,
    clientY: number | undefined,
    currentItem: ILayoutItem,
  ): boolean => {
    if(!props.allowCrossGridDrag || crossGridDraggedId === null) {
      return false;
    }

    const targetZone = findCrossGridZoneAt(clientX ?? Number.NaN, clientY ?? Number.NaN, props.layoutId as string);
    crossGridDraggedId = null;

    if(!targetZone) {
      return false;
    }

    if(targetZone.isExternalDropDisabled()) {
      // Rejected — emitted on the *target* grid (that's what
      // targetZone.rejectDrop does), not this one. This grid's own item
      // stays exactly where it was before the drag, as if the
      // cross-grid attempt never happened: the caller falls through to
      // its own normal end-of-drag handling rather than treating this
      // as accepted, so the item still completes its (purely internal)
      // drag-end move/compaction there.
      targetZone.rejectDrop(id, props.layoutId as string);
      return false;
    }

    // Accepted — hand the current item data to the target grid, then
    // remove it from this one entirely. No moveElement()/compaction
    // call for *this* grid's own layout: the item no longer belongs to
    // it at all, so there's nothing left here to move or compact.
    targetZone.acceptDrop({ ...currentItem }, props.layoutId as string);
    const removedIndex = props.layout.findIndex(entry => entry.i === id);
    if(removedIndex !== -1) {
      // In-place mutation (splice), not filter — see acceptDrop's own
      // comment above for why: this needs to change the same array
      // reference `props.layout` already points to, not produce a new
      // one only reachable via the `update:layout` emit below.
      props.layout.splice(removedIndex, 1);
    }
    emit(EGridLayoutEvent.LAYOUT_UPDATE, props.layout);
    getCompactor(props.compactType! as ECompactType).compact(props.layout, props.colNum as number, {
      compactType: props.compactType! as ECompactType,
    });
    eventBus.emit(`compact`);
    updateHeight();
    originalLayout.value = props.layout;
    emit(EGridLayoutEvent.DRAG_END, id);
    emit(EGridLayoutEvent.LAYOUT_UPDATED, props.layout);
    nextTick(() => {
      isDragging.value = false;
    });
    return true;
  };

  return { handleDragEnd, handleDragStart, setCrossGridDragEnabled, teardown };
}

import { Ref } from 'vue';
import { EGridItemEvent } from '@/core/griditem/enums/EGridItemEvents';
import { IEventsData } from '@/core/common/interfaces/event-bus.interfaces';
import { IGridItemComposableContext } from './grid-item-composable-context';

/** One grid unit per keypress, in both axes — matches the smallest unit the mouse-driven path can produce, and keeps a single keypress predictable. */
const STEP = 1;

/**
 * Keyboard-operable alternative to mouse-driven dragging/resizing —
 * previously the only way to move or resize a `GridItem` at all,
 * regardless of `enableEditMode`, was a mouse or touch drag (see
 * docs/REFACTORING.md's accessibility note). Focus the item and:
 *
 * - **Arrow keys** move it by one grid unit, if draggable.
 * - **Shift + arrow keys** resize it by one grid unit, if resizable.
 *
 * Each keypress is treated as a single, atomic, already-"ended" gesture
 * (there's no keyboard equivalent of a continuous drag to preview mid-way
 * through) — it emits the same `MOVE`/`MOVED` or `RESIZE`/`RESIZED` pairs
 * and the same eventBus `dragEvent`/`resizeEvent` message
 * (`eventType: 'dragend'`/`'resizeend'`) the mouse-driven composables emit
 * on release, so `GridLayout`'s compaction/collision handling applies
 * identically regardless of which input method triggered the change.
 *
 * Deliberately scoped to single-unit steps rather than a full WAI-ARIA
 * grid/application widget pattern (roving tabindex between cells, arrow
 * keys for navigation *and* a separate key for move mode, etc.) — this
 * covers the actual gap (no keyboard alternative existed at all) without
 * redesigning the interaction model for something that isn't a
 * traditional data grid. See docs/ACCESSIBILITY.md.
 */
export function useGridItemKeyboard(
  ctx: IGridItemComposableContext & { draggable: Ref<boolean | null>; resizable: Ref<boolean | null> },
): { handleKeydown: (event: KeyboardEvent) => void } {
  const {
    cols,
    draggable,
    editModeEnabled,
    emit,
    eventBus,
    innerH,
    innerW,
    innerX,
    innerY,
    maxRows,
    props,
    renderRtl,
    resizable,
  } = ctx;

  const moveBy = (dx: number, dy: number): void => {
    const x = Math.max(Math.min(innerX.value + dx, cols.value - innerW.value), 0);
    const y = Math.max(Math.min(innerY.value + dy, maxRows.value - innerH.value), 0);
    if(x === innerX.value && y === innerY.value) {
      return;
    }

    emit(EGridItemEvent.MOVE, props.i, x, y);
    emit(EGridItemEvent.MOVED, props.i, x, y);

    // A synthetic 'dragstart' immediately before 'dragend', at the
    // pre-move position — not skipped straight to 'dragend' the way
    // this used to. Bug fix: GridLayout's multiSelect group-move logic
    // snapshots passenger positions on 'dragstart' and applies the
    // delta on 'dragmove'/'dragend'; without a 'dragstart' first, a
    // keyboard-driven move of a selected item never moved the rest of
    // the selection, only a mouse/touch drag did. Treating each
    // keypress as its own complete start-to-end gesture (rather than
    // trying to retrofit group-move to work from a single event) keeps
    // this consistent with how the mouse-driven path already works.
    const startData: IEventsData = {
      eventType: `dragstart`,
      h: innerH.value,
      i: props.i,
      w: innerW.value,
      x: innerX.value,
      y: innerY.value,
    };
    eventBus.emit(`dragEvent`, startData);

    const data: IEventsData = {
      eventType: `dragend`,
      h: innerH.value,
      i: props.i,
      w: innerW.value,
      x,
      y,
    };
    eventBus.emit(`dragEvent`, data);
  };

  const resizeBy = (dw: number, dh: number): void => {
    let w = innerW.value + dw;
    let h = innerH.value + dh;
    // The `?? Infinity`/`?? 1` fallbacks below are type-necessary, not
    // runtime-reachable — confirmed directly, not assumed: a fresh
    // coverage report flagged all four as uncovered branches, and tracing
    // why confirmed `props.maxW`/`minW`/`maxH`/`minH` are guaranteed
    // already-concrete numbers (`Infinity`/`Infinity`/`1`/`1` by default)
    // via `GridItem.vue`'s own `withDefaults()` call, before this
    // composable ever receives them through `ctx.props` — so the `??`
    // operator's own right-hand side can never execute at runtime.
    // They're kept anyway because `IGridItemComposableContext.props` is
    // typed as the raw `IGridItemProps` interface (where these fields are
    // `number | undefined`, genuinely optional at the type level, since
    // that interface has no way to express "already resolved by
    // withDefaults") — removing them entirely would be a real TypeScript
    // error here (`Math.min`/`Math.max` require `number`, not `number |
    // undefined`), not just a stylistic no-op.
    /* v8 ignore next -- see the comment above: type-necessary, not runtime-reachable. */
    w = Math.max(Math.min(w, cols.value - innerX.value, props.maxW ?? Infinity), props.minW ?? 1);
    /* v8 ignore next -- same rationale as the line above; a single `v8 ignore next 2` above both lines was tried first and only suppressed the first line's own branches, not this one's, so each line gets its own explicit directive instead. */
    h = Math.max(Math.min(h, maxRows.value - innerY.value, props.maxH ?? Infinity), props.minH ?? 1);
    if(w === innerW.value && h === innerH.value) {
      return;
    }

    emit(EGridItemEvent.RESIZE, props.i, h, w, h, w);
    emit(EGridItemEvent.RESIZED, props.i, h, w, h, w);

    // Same rationale as moveBy's own synthetic 'resizestart' above — so
    // group-resize (multiSelect) engages for keyboard-driven resizes too.
    const startData: IEventsData = {
      eventType: `resizestart`,
      h: innerH.value,
      i: props.i,
      w: innerW.value,
      x: innerX.value,
      y: innerY.value,
    };
    eventBus.emit(`resizeEvent`, startData);

    const data: IEventsData = {
      eventType: `resizeend`,
      h,
      i: props.i,
      w,
      x: innerX.value,
      y: innerY.value,
    };
    eventBus.emit(`resizeEvent`, data);
  };

  /**
   * Attach as a `keydown` listener on the item's root element. No-ops
   * (and doesn't call `preventDefault`) for any key other than the plain
   * or Shift-modified arrows, so it never interferes with normal keyboard
   * navigation, a consumer's own key handling inside the item's slot
   * content, or — importantly — OS/browser/assistive-technology shortcuts
   * that commonly use Ctrl/Alt/Meta+Arrow (virtual desktop switching,
   * screen reader navigation, etc.). Holding any of those alongside an
   * arrow key is treated as "not ours" and passed through untouched.
   */
  const handleKeydown = (event: KeyboardEvent): void => {
    if(props.isStatic || !editModeEnabled.value) {
      return;
    }
    if(event.ctrlKey || event.altKey || event.metaKey) {
      return;
    }

    const deltas: Record<string, [number, number]> = {
      ArrowDown: [0, STEP],
      ArrowLeft: [-STEP, 0],
      ArrowRight: [STEP, 0],
      ArrowUp: [0, -STEP],
    };
    const delta = deltas[event.key];
    if(!delta) {
      return;
    }

    // ArrowLeft/Right are physical directions; innerX increasing moves the
    // item toward the visual right in LTR but toward the visual left in
    // RTL (see calcPosition's `right = ...` computation, which increases
    // with x). Flipping the horizontal delta here keeps the physical key
    // pressed matching the physical direction the item visually moves,
    // regardless of rendering direction — the same property the
    // mouse-driven path aims for (see docs/ACCESSIBILITY.md for the
    // caveat that RTL handling isn't as thoroughly verified as LTR).
    const [rawDx, dy] = delta;
    const dx = renderRtl.value ? -rawDx : rawDx;

    if(event.shiftKey) {
      if(!resizable.value) {
        return;
      }
      event.preventDefault();
      resizeBy(dx, dy);
    } else {
      if(!draggable.value) {
        return;
      }
      event.preventDefault();
      moveBy(dx, dy);
    }
  };

  return {
    handleKeydown,
  };
}

import { computed, ComputedRef, ref, Ref } from 'vue';
import { IGridLayoutProps } from '../grid-layout-props.interface';
import { EGridLayoutEvent } from '@/core/gridlayout/enums/EGridLayoutEvents';
import { IItemClickedData } from '@/core/griditem/interfaces/grid-item.interfaces';
import { computeRangeSelection } from '@/core/gridlayout/helpers/selection-range-helper';

/** Dependencies `useMultiSelect` needs from `GridLayout.vue`. */
export interface IUseMultiSelectContext {
  props: IGridLayoutProps;
  /** Vue's own overloaded `defineEmits` type can't be narrowed past `any` here — see `useCrossGridDrag.ts`'s own `IUseCrossGridDragContext.emit` for the full rationale (tried and reverted two narrower alternatives, both broke real call-site assignment). */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  emit: (...args: any[]) => void;
}

/** Return shape of {@link useMultiSelect}. */
export interface IUseMultiSelectReturn {
  backgroundClickHandler: (event: MouseEvent) => void;
  clearSelection: () => void;
  deselectItem: (id: string | number) => void;
  itemClickedHandler: (data: IItemClickedData) => void;
  pruneSelection: () => void;
  /**
   * The raw `Set` ref itself, not just the high-level methods above —
   * unlike `useUndoRedo`'s internal state (which stays fully private
   * behind named methods), `dragEvent`/`resizeEvent`'s own group-move/
   * group-resize logic reads this directly (`.has(id)`, iterating via
   * `Array.from(selectedItemIds.value, ...)`) to apply a delta to every
   * other selected item — that logic stays in `GridLayout.vue` itself
   * (it's part of the drag/resize event handlers, not multi-select
   * management per se), so it needs real read access to the live set,
   * not a method wrapping it.
   */
  selectedItemIds: Ref<Set<string | number>>;
  selectedItems: ComputedRef<(string | number)[]>;
  selectItem: (id: string | number, additive?: boolean) => void;
  toggleItemSelection: (id: string | number) => void;
}

/**
 * Extracted from `GridLayout.vue` (see `docs/REFACTORING.md`'s code
 * review finding on this file's own size, and the parallel `useUndoRedo`
 * extraction) — `multiSelect`'s selection-management state and the two
 * click handlers driving it. The group move/resize logic that actually
 * *applies* the selection during a drag/resize gesture stays in
 * `GridLayout.vue`'s own `dragEvent`/`resizeEvent` (see `selectedItemIds`'s
 * own doc comment above for why), reading `selectedItemIds` directly
 * from this composable's return rather than through a wrapping method.
 */
export function useMultiSelect(ctx: IUseMultiSelectContext): IUseMultiSelectReturn {
  const { props, emit } = ctx;

  /**
   * A `Set`, not an array — every `GridItem`'s own `isSelected` check
   * (read every render, via `thisLayout`, to decide its
   * `vue-grid-item-selected` class) needs an O(1) lookup regardless of
   * selection size, not an O(n) `.includes()`.
   */
  const selectedItemIds = ref<Set<string | number>>(new Set());

  /**
   * The anchor for a future Shift-click range — the last item selected
   * without Shift (a plain click, or a Ctrl/Cmd toggle), matching the
   * standard file-explorer/spreadsheet convention: the range always
   * spans from this fixed point to whatever's Shift-clicked next, not
   * from the *previous* Shift-click target (which would make repeated
   * Shift-clicks compound unpredictably instead of always re-anchoring
   * to the same starting point). `null` until the first click of any
   * kind — a Shift-click with no anchor yet has nothing to range from,
   * so `itemClickedHandler` below falls back to a plain select in that
   * case.
   */
  const lastAnchorId = ref<string | number | null>(null);

  /** Reactive, read-only array view of the current selection — the exposed public form. `selectedItemIds` (a `Set`) stays internal; `GridItem`'s own `isSelected` check via `thisLayout` uses it directly for O(1) lookups. */
  const selectedItems = computed(() => Array.from(selectedItemIds.value));

  const emitSelectionChanged = (): void => {
    emit(EGridLayoutEvent.SELECTION_CHANGED, Array.from(selectedItemIds.value));
  };

  /**
   * Selects `id`. `additive: false` (the default — a plain click)
   * replaces the entire selection with just this one item; `additive:
   * true` (Shift/Ctrl/Cmd+click) adds it to whatever's already
   * selected without clearing the rest.
   */
  const selectItem = (id: string | number, additive = false): void => {
    selectedItemIds.value = additive ? new Set([...selectedItemIds.value, id]) : new Set([id]);
    emitSelectionChanged();
  };

  /** Removes `id` from the selection, if present. A no-op (no event fired) if it wasn't selected. */
  const deselectItem = (id: string | number): void => {
    if(!selectedItemIds.value.has(id)) {
      return;
    }
    const next = new Set(selectedItemIds.value);
    next.delete(id);
    selectedItemIds.value = next;
    emitSelectionChanged();
  };

  /** Adds `id` to the selection if not already present, removes it otherwise — the Shift/Ctrl/Cmd+click gesture. */
  const toggleItemSelection = (id: string | number): void => {
    if(selectedItemIds.value.has(id)) {
      deselectItem(id);
    } else {
      selectItem(id, true);
    }
  };

  /** Empties the selection entirely — the "click empty grid background" gesture, also callable directly. A no-op (no event fired) if nothing was selected. Also clears `lastAnchorId`: a range anchor pointing at an item outside the (now-empty) selection would be a confusing starting point for whatever's Shift-clicked next. */
  const clearSelection = (): void => {
    lastAnchorId.value = null;
    if(selectedItemIds.value.size === 0) {
      return;
    }
    selectedItemIds.value = new Set();
    emitSelectionChanged();
  };

  /**
   * Removes any selected id no longer present in `props.layout` — bug
   * fix: a selected item's id used to linger in `selectedItemIds`
   * (and so the exposed `selectedItems`) indefinitely after that item
   * was removed from the layout (closed, or removed by the consumer's
   * own code), a dangling reference to something that no longer
   * exists. Wired to the same `props.layout.length` watcher that
   * already reacts to add/remove — a length change is exactly when
   * this can happen. Also clears `lastAnchorId` specifically when *it*
   * no longer matches a real item — a range computed from a removed
   * anchor would silently fall back to `computeRangeSelection`'s own
   * "anchor not found" case (just the target alone), which is
   * confusing rather than useful; resetting it here means the next
   * Shift-click with no valid anchor instead falls through to a plain
   * select, the same well-defined "no anchor yet" behavior a fresh
   * grid starts with.
   */
  const pruneSelection = (): void => {
    if(lastAnchorId.value !== null && !props.layout.some(item => item.i === lastAnchorId.value)) {
      lastAnchorId.value = null;
    }
    if(selectedItemIds.value.size === 0) {
      return;
    }
    const currentIds = new Set(props.layout.map(item => item.i));
    const next = new Set(Array.from(selectedItemIds.value).filter(id => currentIds.has(id)));
    if(next.size !== selectedItemIds.value.size) {
      selectedItemIds.value = next;
      emitSelectionChanged();
    }
  };

  /**
   * eventBus `itemClicked` listener — every `GridItem`'s own click
   * handler (after suppressing the trailing click a drag/resize
   * gesture can still dispatch) sends this regardless of whether
   * `multiSelect` is on, since a `GridItem` has no way to know this
   * grid's own prop value itself; the early return here is what
   * actually gates the feature being off by default.
   *
   * Shift-click range-selection: extends from `lastAnchorId` (the last
   * plain/Ctrl-click) to the clicked item, inclusive, via `core`'s own
   * `computeRangeSelection` — *replacing* the current selection with
   * that range, matching the standard desktop convention (not
   * additive; a Shift-click after an unrelated Ctrl-click selection
   * doesn't merge with it). Falls back to a plain select if there's no
   * anchor yet (the very first click on a fresh grid) — a range needs
   * two ends to mean anything, and a lone Shift-click has only one.
   * Deliberately does *not* update `lastAnchorId` on a Shift-click
   * itself: see that ref's own doc comment for why the anchor should
   * stay fixed across repeated Shift-clicks.
   */
  const itemClickedHandler = (data: IItemClickedData): void => {
    if(!props.multiSelect) {
      return;
    }
    if(data.shiftKey && lastAnchorId.value !== null) {
      const range = computeRangeSelection(props.layout, lastAnchorId.value, data.i);
      selectedItemIds.value = new Set(range);
      emitSelectionChanged();
      return;
    }
    if(data.shiftKey || data.ctrlKey || data.metaKey) {
      toggleItemSelection(data.i);
    } else {
      selectItem(data.i, false);
    }
    lastAnchorId.value = data.i;
  };

  /**
   * Clears the selection when the click landed on the grid's own root
   * element directly — not bubbled up from a `GridItem` (or anything
   * else) inside it. `event.target === event.currentTarget` is exactly
   * that distinction: a click that started somewhere nested would have
   * a different `target` than `currentTarget` by the time it reaches
   * this listener.
   */
  const backgroundClickHandler = (event: MouseEvent): void => {
    if(props.multiSelect && event.target === event.currentTarget) {
      clearSelection();
    }
  };

  return {
    backgroundClickHandler,
    clearSelection,
    deselectItem,
    itemClickedHandler,
    pruneSelection,
    selectedItemIds,
    selectedItems,
    selectItem,
    toggleItemSelection,
  };
}

import { ComputedRef, Ref } from 'vue';
import { calcColWidth } from '@/core/griditem/helpers/grid-item-calculate-helper';
import { IPlaceholder } from '@/core/gridlayout/interfaces/layout-data.interface';
import { EGridLayoutEvent } from '@/core/gridlayout/enums/EGridLayoutEvents';
import { IGridLayoutProps } from '../grid-layout-props.interface';

/** Dependencies `useOutsideDrop` needs from `GridLayout.vue`. */
export interface IUseOutsideDropContext {
  props: IGridLayoutProps;
  /** Vue's own overloaded `defineEmits` type can't be narrowed past `any` here — see `useCrossGridDrag.ts`'s own `IUseCrossGridDragContext.emit` for the full rationale (tried and reverted two narrower alternatives, both broke real call-site assignment). */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  emit: (...args: any[]) => void;
  /** `GridLayout`'s own root element ref — where the native drag-and-drop listeners attach. */
  refsLayout: Ref<HTMLElement>;
  /** The container's last measured pixel width — used for the same grid-position-from-pixel math the rest of this file uses. Accepts a plain `Ref` or a `ComputedRef` (e.g. `GridLayout.vue`'s own min/maxW-adjusted `effectiveWidth`) since this composable only ever reads `.value`, never writes it. */
  width: Ref<number | null> | ComputedRef<number | null>;
  placeholder: Ref<IPlaceholder>;
  isDragging: Ref<boolean>;
}

/**
 * Encapsulates `allowOutsideDrop`: native HTML5 drag-and-drop from
 * outside the grid system entirely (e.g. a `draggable="true"` element
 * elsewhere on the page, not another `GridItem`) — distinct from
 * `allowCrossGridDrag` (`useCrossGridDrag.ts`), which is for dragging an
 * *existing* item between two `GridLayout` instances via interact.js's
 * own pointer-based dragging, not the browser's native drag-and-drop API.
 *
 * Extracted from `GridLayout.vue` as part of the structural cleanup
 * flagged in `docs/REFACTORING.md`'s Structural section — see
 * `docs/ARCHITECTURE.md` for the full design this composable
 * implements, and finding #68 there for the extraction itself.
 */
export function useOutsideDrop(ctx: IUseOutsideDropContext): { setOutsideDropEnabled: (enabled: boolean) => void } {
  const { props, emit, refsLayout, width, placeholder, isDragging } = ctx;

  /**
   * `dragenter`/`dragleave` bubble from every descendant element, firing
   * far more often than just "entered/left the grid as a whole" — an
   * enter-count (incremented on `dragenter`, decremented on
   * `dragleave`, treated as "actually left" only once it returns to
   * zero) is the standard workaround, tracking net entries/exits rather
   * than reacting to every single bubble individually, which would
   * otherwise flicker the placeholder's visibility on and off
   * repeatedly while the pointer moves around inside the grid. Only
   * actually hiding it once the count returns to zero means it stays
   * visible for as long as the drag is anywhere inside the grid, at any
   * depth.
   */
  let dragEnterCount = 0;

  const outsideDropPositionFromEvent = (event: DragEvent): { x: number; y: number } => {
    const rect = refsLayout.value.getBoundingClientRect();
    const margin = props.margin!;
    const colWidth = calcColWidth(width.value ?? rect.width, margin[0], props.colNum as number);
    const left = event.clientX - rect.left;
    const top = event.clientY - rect.top;

    let x = Math.round((left - margin[0]) / (colWidth + margin[0]));
    let y = Math.round((top - margin[1]) / ((props.rowHeight as number) + margin[1]));
    x = Math.max(Math.min(x, (props.colNum as number) - (props.outsideDropWidth as number)), 0);
    y = Math.max(Math.min(y, (props.maxRows as number) - (props.outsideDropHeight as number)), 0);

    return { x, y };
  };

  const outsideDropAccepted = (event: DragEvent): boolean => {
    if(!props.outsideDropAccept) {
      return true;
    }
    return props.outsideDropAccept(event.dataTransfer);
  };

  const onOutsideDragEnter = (event: DragEvent): void => {
    if(!outsideDropAccepted(event)) {
      // Deliberately no preventDefault() here — leaving the browser's
      // own default drag-and-drop handling in place is what tells it
      // this isn't a valid drop target for this particular drag,
      // showing the native "not allowed" cursor rather than this grid's
      // own live placeholder. Not incrementing dragEnterCount either,
      // so a later dragleave for this same rejected drag doesn't
      // decrement it into the negative relative to genuinely-accepted
      // drags that might be in progress from a different element.
      return;
    }
    event.preventDefault();
    dragEnterCount += 1;
  };

  const onOutsideDragOver = (event: DragEvent): void => {
    if(!outsideDropAccepted(event)) {
      return;
    }
    // Required per the HTML5 drag-and-drop spec: without preventDefault()
    // here, the browser never treats this element as a valid drop
    // target, and the native `drop` event below would never fire — see
    // docs/REFACTORING.md #30 for the exact same gotcha caught once
    // already, in an earlier (later replaced) cross-grid approach.
    event.preventDefault();
    const { x, y } = outsideDropPositionFromEvent(event);
    placeholder.value.i = `__outside_drop_placeholder__`;
    placeholder.value.x = x;
    placeholder.value.y = y;
    placeholder.value.w = props.outsideDropWidth as number;
    placeholder.value.h = props.outsideDropHeight as number;
    isDragging.value = true;
  };

  const onOutsideDragLeave = (event: DragEvent): void => {
    event.preventDefault();
    dragEnterCount = Math.max(0, dragEnterCount - 1);
    if(dragEnterCount === 0) {
      isDragging.value = false;
    }
  };

  const onOutsideDrop = (event: DragEvent): void => {
    if(!outsideDropAccepted(event)) {
      return;
    }
    event.preventDefault();
    dragEnterCount = 0;
    isDragging.value = false;
    const { x, y } = outsideDropPositionFromEvent(event);
    emit(EGridLayoutEvent.ITEM_DROPPED_FROM_OUTSIDE, {
      dataTransfer: event.dataTransfer,
      h: props.outsideDropHeight as number,
      w: props.outsideDropWidth as number,
      x,
      y,
    });
  };

  /**
   * Attaches/detaches the four native listeners on `refsLayout.value`.
   * Called once from `onMounted` for the initial `allowOutsideDrop`
   * value, and again whenever that prop changes reactively — the same
   * two-call-site pattern `useCrossGridDrag`'s
   * `setCrossGridDragEnabled` uses, for the same reason (toggling the
   * prop at runtime needs to actually take effect).
   */
  const setOutsideDropEnabled = (enabled: boolean): void => {
    const el = refsLayout.value;
    if(!el) {
      return;
    }
    if(enabled) {
      el.addEventListener(`dragenter`, onOutsideDragEnter);
      el.addEventListener(`dragover`, onOutsideDragOver);
      el.addEventListener(`dragleave`, onOutsideDragLeave);
      el.addEventListener(`drop`, onOutsideDrop);
    } else {
      el.removeEventListener(`dragenter`, onOutsideDragEnter);
      el.removeEventListener(`dragover`, onOutsideDragOver);
      el.removeEventListener(`dragleave`, onOutsideDragLeave);
      el.removeEventListener(`drop`, onOutsideDrop);
      dragEnterCount = 0;
    }
  };

  return { setOutsideDropEnabled };
}

import { Ref, ref } from 'vue';
import { TLayout } from '@/components';
import { cloneLayout } from '@/core/helpers/utils';
import { getBreakpointFromWidth, getColsFromBreakpoint } from '@/core/common/helpers/breakpoints-helper';
import { findOrGenerateResponsiveLayout } from '@/core/gridlayout/helpers/responsive-helper';
import { EGridLayoutEvent } from '@/core/gridlayout/enums/EGridLayoutEvents';
import { ECompactType } from '@/core/gridlayout/enums/ECompactType';
import { TGridLayoutEventBus } from '@/core/gridlayout/interfaces/layout-data.interface';
import { IGridLayoutProps } from '../grid-layout-props.interface';

/** Dependencies `useResponsiveLayout` needs from `GridLayout.vue`. */
export interface IUseResponsiveLayoutContext {
  /** `toRef(props, 'colNum')` — the user-configured column cap. */
  colNum: Ref<number>;
  /** Vue's own overloaded `defineEmits` type can't be narrowed past `any` here — see `useCrossGridDrag.ts`'s own `IUseCrossGridDragContext.emit` for the full rationale (tried and reverted two narrower alternatives, both broke real call-site assignment). */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  emit: (...args: any[]) => void;
  eventBus: TGridLayoutEventBus;
  /** `GridLayout`'s own processed-layout ref, read and written by `responsiveGridLayout`. */
  originalLayout: Ref<TLayout | undefined>;
  props: IGridLayoutProps;
  /** The container's last measured pixel width. */
  width: Ref<number | null>;
}

/**
 * Encapsulates GridLayout's responsive-breakpoint behavior: tracking which
 * layout belongs to which breakpoint, finding-or-generating the layout for
 * a newly-entered breakpoint, and resetting that cache when
 * `responsiveLayouts` changes.
 *
 * Extracted from GridLayout.vue as part of the Phase 2 structural cleanup
 * — see docs/ARCHITECTURE.md and docs/REFACTORING.md.
 */
/** Return shape of {@link useResponsiveLayout}. */
export interface IUseResponsiveLayoutReturn {
  colNumResponsive: Ref<number | undefined>;
  initResponsiveFeatures: () => void;
  lastBreakpoint: Ref<string | null>;
  layouts: Ref<{ [key: string]: TLayout }>;
  responsiveGridLayout: () => void;
}

export function useResponsiveLayout(ctx: IUseResponsiveLayoutContext): IUseResponsiveLayoutReturn {
  const { colNum, emit, eventBus, originalLayout, props, width } = ctx;

  // Layout cache per breakpoint, and the currently active breakpoint.
  const layouts = ref<{ [key: string]: TLayout }>({});
  const lastBreakpoint = ref<string | null>(null);
  const colNumResponsive = ref(props.colNum);

  /**
   * Finds or generates the layout for the current container width's
   * breakpoint, and switches to it — emitting `breakpoint-changed` if the
   * breakpoint actually changed, and `update:layout` either way.
   *
   * **Investigated (not a bug found here):** the React port had a real
   * bug where its own `containerWidth` state seeded at a value
   * (`100`) indistinguishable from a genuine measurement, so its
   * responsive-breakpoint effect could resolve a breakpoint against
   * that seed before any real measurement landed (see the React
   * package's own `docs/PARITY_GAP_IMPLEMENTATION_PLAN.md`, Phase 18).
   * Checked whether `width` here shares that shape: it doesn't, in the
   * common case — `width` seeds at `null` (not a number that could
   * pass for a real measurement), and `onWindowResize()` (the only
   * caller of `responsiveGridLayout()` during normal mount) measures
   * `width.value` synchronously, in the same function call, *before*
   * calling this — unlike React's separate, independently-scheduled
   * effects, there's no window where this function reads a stale
   * `width` after a real measurement already happened elsewhere.
   * **One narrow, unconfirmed edge case remains, not fixed here:** the
   * `props.colNum` watcher in `GridLayout.vue` calls
   * `responsiveGridLayout()` directly (not through `onWindowResize()`),
   * unconditionally, whenever `colNum` changes reactively — if a
   * consumer changes `colNum` before this component's own first
   * `onWindowResize()` call has completed (a real but narrow race, not
   * the guaranteed-every-mount shape the React bug had), `width.value`
   * would still be `null` here, and `getBreakpointFromWidth` would
   * resolve to the lowest-threshold breakpoint (`'xxs'` by default) as
   * a side effect of `null`'s own numeric coercion in that comparison
   * — the same symptom the React bug produced, just via a different,
   * much narrower path. Not fixed as part of this investigation, since
   * it wasn't confirmed as an actually-reachable sequence in normal
   * usage, only as a theoretical one worth flagging for whoever
   * revisits this next.
   */
  const responsiveGridLayout = (): void => {
    const newBreakpoint = getBreakpointFromWidth(props.breakpoints!, width.value as number);
    const newCols = getColsFromBreakpoint(newBreakpoint, props.cols!);
    // responsive cols
    colNumResponsive.value = newCols;

    let colsCompute = newCols;
    // max is colNum which is set by user
    if(colNum.value < colNumResponsive.value) {
      colsCompute = colNum.value;
    }

    if(lastBreakpoint.value != null && !layouts.value[lastBreakpoint.value]) {
      layouts.value[lastBreakpoint.value] = cloneLayout(props.layout);
    }

    // Find or generate a new layout.
    const layout = findOrGenerateResponsiveLayout(
      originalLayout.value as TLayout,
      layouts.value,
      props.breakpoints!,
      newBreakpoint,
      lastBreakpoint.value as string,
      colsCompute,
      props.compactType! as ECompactType,
      props.distributeEvenly!,
    );

    layouts.value[newBreakpoint] = cloneLayout(layout);

    if(lastBreakpoint.value !== newBreakpoint) {
      emit(EGridLayoutEvent.BREAKPOINT_CHANGED, newBreakpoint, layout);
    }

    // new prop sync
    originalLayout.value = layout;

    emit(EGridLayoutEvent.LAYOUT_UPDATE, layout);

    lastBreakpoint.value = newBreakpoint;
    eventBus.emit(`setColNum`, colsCompute);
  };

  /**
   * Reset the per-breakpoint layout cache to whatever the consumer passed
   * in via the `responsiveLayouts` prop. Called once at mount and whenever
   * responsive mode is (re-)entered.
   */
  const initResponsiveFeatures = (): void => {
    layouts.value = { ...props.responsiveLayouts };
  };

  /**
   * @returns
   * - `colNumResponsive` — not currently consumed by `GridLayout.vue` outside this composable; kept for potential external inspection/debugging.
   * - `initResponsiveFeatures` — called from `GridLayout.vue`'s `onMounted` and its `responsive` watcher.
   * - `lastBreakpoint` — re-exposed via `GridLayout`'s `defineExpose` for `GridItem`'s `$parent` access (see `docs/ARCHITECTURE.md`).
   * - `layouts` — re-exposed via `defineExpose`.
   * - `responsiveGridLayout` — called from `GridLayout.vue`'s `onWindowResize` and its `colNum`/`responsive` watchers.
   */
  return {
    colNumResponsive,
    initResponsiveFeatures,
    lastBreakpoint,
    layouts,
    responsiveGridLayout,
  };
}

import { computed, ComputedRef, ref, Ref } from 'vue';
import { TLayout } from '@/components';
import { IGridLayoutProps } from '../grid-layout-props.interface';
import { cloneLayout } from '@/core/helpers/utils';
import { EGridLayoutEvent } from '@/core/gridlayout/enums/EGridLayoutEvents';

/** Dependencies `useUndoRedo` needs from `GridLayout.vue`. */
export interface IUseUndoRedoContext {
  props: IGridLayoutProps;
  /** Vue's own overloaded `defineEmits` type can't be narrowed past `any` here — see `useCrossGridDrag.ts`'s own `IUseCrossGridDragContext.emit` for the full rationale (tried and reverted two narrower alternatives, both broke real call-site assignment). */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  emit: (...args: any[]) => void;
  updateHeight: () => void;
  /** Re-runs compaction — `undo()`/`redo()` call this after restoring a previous/next layout, since the restored layout isn't guaranteed to already be fully compacted. */
  runCompaction: () => void;
}

/**
 * Extracted from `GridLayout.vue` (see `docs/REFACTORING.md`'s code
 * review finding on this file's own size) — undo/redo history, at
 * committed-change granularity (drag start→end, resize start→end, item
 * add/remove, `compactNow()`/`rearrange()`), not per intermediate
 * drag-move frame. Opt-in via `enableUndoRedo`, capped at
 * `undoHistoryLimit` snapshots.
 *
 * `commitUndoPoint(before)` takes the pre-mutation state explicitly,
 * rather than reading a single shared "last known state" variable at
 * call time — deliberately, after finding that reading it implicitly
 * doesn't work for a gesture: calling a would-be `pushUndoPoint()` at
 * `dragstart` (before anything has actually moved) can only ever see
 * "nothing has changed since the last commit yet", since the change
 * itself happens later, at `dragend` — a single implicit-comparison
 * function called at the *start* of a gesture can never detect the
 * change that gesture is about to make. `captureDragStart`/
 * `captureResizeStart` instead only *capture* the pre-gesture snapshot;
 * `commitDragEnd`/`commitResizeEnd` call `commitUndoPoint` themselves,
 * *after* the position update and compaction have already run, passing
 * that captured snapshot in as `before` — at which point comparing it
 * against the now-current `props.layout` actually reflects the
 * gesture's real effect.
 *
 * For the length watcher (item add/remove) and `compactNow()`, the
 * mutation itself already happens synchronously before either can call
 * `commitUndoPoint`, so `lastSnapshot` (only ever updated by a
 * successful commit or `initLastSnapshot`, never by the mutation
 * itself) is *already* the correct "before" value at the point each of
 * them calls it — no separate capture step needed for those two.
 *
 * Bug fix carried over from when this lived directly in `GridLayout.vue`:
 * `lastSnapshot` must only ever be captured *after* compaction has run,
 * never before — capturing it first would clone a layout item still
 * carrying a raw, uncompacted value (e.g. `y: Infinity`, a common
 * placement convention), which `cloneLayout`'s JSON round-trip silently
 * corrupts (`JSON.stringify(Infinity)` produces `null`), permanently
 * breaking that item in every future undo/redo snapshot referencing
 * it. `undo()`/`redo()` themselves had the identical ordering mistake
 * independently — both fixed together. See `docs/REFACTORING.md` #105.
 */
/** Return shape of {@link useUndoRedo}. */
export interface IUseUndoRedoReturn {
  canRedo: ComputedRef<boolean | undefined>;
  canUndo: ComputedRef<boolean | undefined>;
  captureDragStart: () => void;
  captureResizeStart: () => void;
  commitDragEnd: () => void;
  commitFromLastSnapshot: () => void;
  commitResizeEnd: () => void;
  commitUndoPoint: (before: TLayout) => void;
  initLastSnapshot: () => void;
  redo: () => void;
  undo: () => void;
}

export function useUndoRedo(ctx: IUseUndoRedoContext): IUseUndoRedoReturn {
  const { props, emit, updateHeight, runCompaction } = ctx;

  const undoStack: Ref<TLayout[]> = ref<TLayout[]>([]);
  const redoStack: Ref<TLayout[]> = ref<TLayout[]>([]);
  let lastSnapshot: TLayout = [];
  let dragStartSnapshot: TLayout | null = null;
  let resizeStartSnapshot: TLayout | null = null;

  const canUndo = computed(() => props.enableUndoRedo && undoStack.value.length > 0);
  const canRedo = computed(() => props.enableUndoRedo && redoStack.value.length > 0);

  const commitUndoPoint = (before: TLayout): void => {
    if(!props.enableUndoRedo) {
      return;
    }
    // No-op if nothing has actually changed — without this, e.g. a
    // drag that snaps back to its own start position, or a
    // `compactNow()` on an already-fully-compacted layout, would still
    // consume an undo slot for a change that never happened.
    if(JSON.stringify(before) === JSON.stringify(props.layout)) {
      return;
    }
    undoStack.value.push(before);
    if(undoStack.value.length > (props.undoHistoryLimit as number)) {
      undoStack.value.shift();
    }
    redoStack.value = [];
    lastSnapshot = cloneLayout(props.layout);
  };

  const undo = (): void => {
    if(!props.enableUndoRedo || undoStack.value.length === 0) {
      return;
    }
    const previous = undoStack.value.pop() as TLayout;
    redoStack.value.push(cloneLayout(props.layout));
    props.layout.splice(0, props.layout.length, ...cloneLayout(previous));
    // `lastSnapshot` captured after runCompaction(), not before — see
    // this file's own doc comment above for the full account.
    runCompaction();
    lastSnapshot = cloneLayout(props.layout);
    updateHeight();
    emit(EGridLayoutEvent.LAYOUT_UPDATE, props.layout);
    emit(EGridLayoutEvent.LAYOUT_UPDATED, props.layout);
  };

  const redo = (): void => {
    if(!props.enableUndoRedo || redoStack.value.length === 0) {
      return;
    }
    const next = redoStack.value.pop() as TLayout;
    undoStack.value.push(cloneLayout(props.layout));
    props.layout.splice(0, props.layout.length, ...cloneLayout(next));
    // See undo()'s own comment just above for why this is captured
    // after runCompaction(), not before.
    runCompaction();
    lastSnapshot = cloneLayout(props.layout);
    updateHeight();
    emit(EGridLayoutEvent.LAYOUT_UPDATE, props.layout);
    emit(EGridLayoutEvent.LAYOUT_UPDATED, props.layout);
  };

  /** Called once at `onMounted` — establishes the initial "before" baseline so the very first item add/remove has a real snapshot to compare against. */
  const initLastSnapshot = (): void => {
    lastSnapshot = cloneLayout(props.layout);
  };

  /** Called at `dragstart` — captures the pre-drag layout so `commitDragEnd` has the real "before" state to commit. */
  const captureDragStart = (): void => {
    dragStartSnapshot = cloneLayout(props.layout);
  };

  /** Called at `dragend` — commits the captured pre-drag snapshot, then clears it (a no-op if `captureDragStart` was never called, e.g. a drag that started before `enableUndoRedo` was toggled on). */
  const commitDragEnd = (): void => {
    if(dragStartSnapshot) {
      commitUndoPoint(dragStartSnapshot);
      dragStartSnapshot = null;
    }
  };

  /** Called at `resizestart` — same as `captureDragStart`, for the resize gesture. */
  const captureResizeStart = (): void => {
    resizeStartSnapshot = cloneLayout(props.layout);
  };

  /** Called at `resizeend` — same as `commitDragEnd`, for the resize gesture. */
  const commitResizeEnd = (): void => {
    if(resizeStartSnapshot) {
      commitUndoPoint(resizeStartSnapshot);
      resizeStartSnapshot = null;
    }
  };

  /** Called from the `props.layout.length` watcher (item add/remove), after compaction has already run — commits `lastSnapshot` (the state just before this change) as the "before" value. */
  const commitFromLastSnapshot = (): void => {
    commitUndoPoint(lastSnapshot);
  };

  return {
    canRedo,
    canUndo,
    captureDragStart,
    captureResizeStart,
    commitDragEnd,
    commitFromLastSnapshot,
    commitResizeEnd,
    commitUndoPoint,
    initLastSnapshot,
    redo,
    undo,
  };
}

