      await nextTick();
      await nextTick();
      await nextTick();

      wrapper.vm.compactNow();
      await nextTick();
      expect(wrapper.vm.layout.find((item: { i: string }) => item.i === `1`)?.y).toBe(2);

      wrapper.vm.undo();
      await nextTick();

      expect(wrapper.vm.layout.find((item: { i: string }) => item.i === `1`)?.y).toBe(5);
    });

